package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

@Timeout(120)
class AdjacencyApplierShutdownTest {

	@Test
	@SuppressWarnings("unchecked")
	void closeReleasesPredecessorRetainedByCancelledPreparation() throws Exception {
		ExecutorService executor = Executors.newFixedThreadPool(2);
		ExecutorAdjacencyWorkerPool workers = new ExecutorAdjacencyWorkerPool(executor);
		SteppingApplierScheduler scheduler = new SteppingApplierScheduler();
		AdjacencyCommitLog log = new AdjacencyCommitLog(0);
		AdjacencyIndexOps<Object, Object, Object> ops = mock(AdjacencyIndexOps.class);
		Object base = new Object();
		when(ops.build(any())).thenReturn(new AdjacencyIndexOps.Candidate<>(base, null, 0, 0));
		AdjacencyApplier<Object, Object, Object> applier = new AdjacencyApplier<>(log, ops,
				(b, o, index) -> null, workers, scheduler, Long.MAX_VALUE, 1000);
		CountDownLatch running = new CountDownLatch(2);
		CountDownLatch release = new CountDownLatch(1);
		try {
			applier.start();
			applier.requestRebuild();
			scheduler.drain();
			assertTrue(workers.awaitIdle(5, TimeUnit.SECONDS));
			scheduler.drain();
			assertEquals(AdjacencyState.Status.SERVING, applier.state().status());
			AdjacencyState<Object, Object> predecessor = applier.state();
			assertEquals(1, predecessor.referenceCount());
			for (int i = 0; i < 2; i++) {
				workers.submit(() -> {
					running.countDown();
					release.await();
					return null;
				}, outcome -> {
				});
			}
			assertTrue(running.await(5, TimeUnit.SECONDS));
			AdjacencyDelta delta = mock(AdjacencyDelta.class);
			when(delta.revision()).thenReturn(1L);
			when(delta.bytes()).thenReturn(32L);
			log.stage(1, CompletableFuture.completedFuture(delta));
			log.confirm();
			scheduler.drain();
			assertTrue(applier.prepareInFlight());
			assertEquals(2, predecessor.referenceCount(), "queued preparation retains its predecessor");
			applier.requestClose();
			scheduler.drain();
			assertEquals(AdjacencyState.Status.CLOSED, applier.state().status());
			assertEquals(1, predecessor.referenceCount(), "only queued preparation still holds the predecessor");
			applier.close();
			assertTrue(workers.awaitIdle(0, TimeUnit.NANOSECONDS));
			assertFalse(applier.prepareInFlight());
			assertEquals(0, predecessor.referenceCount());
			verify(ops, times(1)).releaseBase(base);
			verify(ops, never()).prepare(any(AdjacencyCommitLog.Record.class), any(), any());
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		} finally {
			release.countDown();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		}
	}
}
